package org.agentfrc.lesson;
import edu.wpi.first.wpilibj.simulation.*;
/** Moving mount, fixed world floor. Controller receives only raw wheel/roller encoder and ideal beam IO. */
public final class MovingNoteRig implements AutoCloseable {
 public final MovingNoteController controller;public final MovingNotePassageAssessor assessor;private final MovingNotePlant plant;private final MovingNotePlant.Config config;private final EncoderSim left,right,roller;private final DIOSim beam;private final PWMSim leftPwm,rightPwm,rollerPwm;private final double leftScale;private final int beamFault;private MovingNotePlant.Sample last;private double time;
 public MovingNoteRig(MovingNotePlant.Config config){this(config,1,0);}public MovingNoteRig(MovingNotePlant.Config config,double leftScale,int beamFault){if((leftScale!=1&&leftScale!=-1)||beamFault<0||beamFault>2)throw new IllegalArgumentException("Declared IO faults only");this.config=config;this.leftScale=leftScale;this.beamFault=beamFault;plant=new MovingNotePlant(config);controller=new MovingNoteController();assessor=new MovingNotePassageAssessor(config.note());left=EncoderSim.createForChannel(4);right=EncoderSim.createForChannel(6);roller=EncoderSim.createForChannel(0);beam=new DIOSim(2);leftPwm=new PWMSim(1);rightPwm=new PWMSim(2);rollerPwm=new PWMSim(0);last=plant.sample(0,0,0);inject();assessor.observe(0,last.relativeX(),last.noteZ(),last.noteVx()-last.bodyV(),last.rollerNormal());}
 private void inject(){left.setCount((int)Math.round(last.leftAngle()/(2*Math.PI/2048)*leftScale));right.setCount((int)Math.round(last.rightAngle()/(2*Math.PI/2048)));roller.setCount((int)Math.round(last.sleeveAngle()/(2*Math.PI/2048)));beam.setValue(beamFault==1?false:beamFault==2?true:!NoteContactPlant.beamBlocked(config.note(),last.relativeX(),0));RoboRioSim.setVInVoltage(last.bus());}
 public MovingNotePlant.Sample step(boolean enabled,int substeps){if(substeps!=200&&substeps!=400)throw new IllegalArgumentException("Reviewed refinement levels only");controller.periodic(enabled);for(int i=0;i<substeps;i++){last=plant.step(leftPwm.getSpeed(),rightPwm.getSpeed(),rollerPwm.getSpeed(),.02/substeps);time+=.02/substeps;assessor.observe(time,last.relativeX(),last.noteZ(),last.noteVx()-last.bodyV(),last.rollerNormal());}inject();return last;}
 public MovingNotePlant.Sample lastSample(){return last;}public double maxEvaluatedRollerNormal(){return plant.maxEvaluatedRollerNormal();}
 @Override public void close(){controller.close();}
}
